/***************************************************************************/
/* The main packet dissector function
 */
static gboolean dissect_rtps(tvbuff_t *tvb, packet_info *pinfo, proto_tree *tree, gint offset)
{
  proto_item   *ti;
  proto_tree   *rtps_tree, *rtps_submessage_tree;
  guint8       submessageId, flags, majorRev;
  guint16      version, vendor_id;
  gboolean     is_ping;
  guint        encoding;
  gint         next_submsg, octets_to_next_header;
  int          sub_hf;
  const value_string *sub_vals;
  endpoint_guid guid;
  endpoint_guid dst_guid;
  guint32 magic_number;
  gchar domain_id_str[RTPS_UNKNOWN_DOMAIN_ID_STR_LEN] = RTPS_UNKNOWN_DOMAIN_ID_STR;
  /* Check 'RTPS' signature:
   * A header is invalid if it has less than 16 octets
   */
  if (tvb_reported_length_remaining(tvb, offset) < 16)
    return FALSE;

  magic_number = tvb_get_ntohl(tvb, offset);
  if (magic_number != RTPX_MAGIC_NUMBER &&
      magic_number != RTPS_MAGIC_NUMBER) {
      return FALSE;
  }
  /* Distinguish between RTPS 1.x and 2.x here */
  majorRev = tvb_get_guint8(tvb,offset+4);
  if ((majorRev != 1) && (majorRev != 2))
    return FALSE;

  /* No fields have been set in either GUID yet. */
  guid.fields_present = 0;
  dst_guid.fields_present = 0;

  col_set_str(pinfo->cinfo, COL_PROTOCOL, "RTPS");
  col_clear(pinfo->cinfo, COL_INFO);

  /* create display subtree for the protocol */
  ti = proto_tree_add_item(tree, proto_rtps, tvb, 0, -1, ENC_NA);
  rtps_tree = proto_item_add_subtree(ti, ett_rtps);

  /* magic */
  proto_tree_add_item(rtps_tree, hf_rtps_magic, tvb, 0, 4, ENC_NA | ENC_ASCII);

  /*  Protocol Version */
  version = rtps_util_add_protocol_version(rtps_tree, tvb, offset+4);

  /*  Vendor Id  */
  vendor_id = rtps_util_add_vendor_id(rtps_tree, tvb, offset+6);

  is_ping = rtps_is_ping(tvb, pinfo, offset+8);

  if (!is_ping) {
    if (version < 0x0200)
      rtps_util_add_guid_prefix_v1(rtps_tree, tvb, offset+8,
                        hf_rtps_guid_prefix_v1, hf_rtps_host_id, hf_rtps_app_id,
                        hf_rtps_app_id_instance_id, hf_rtps_app_id_app_kind, NULL);
    else
      rtps_util_add_guid_prefix_v2(rtps_tree, tvb, offset+8, hf_rtps_guid_prefix_src,
          hf_rtps_host_id, hf_rtps_app_id, hf_rtps_sm_instance_id, hf_rtps_guid_prefix);

    guid.host_id = tvb_get_ntohl(tvb, offset+8);
    guid.app_id = tvb_get_ntohl(tvb, offset+12);
    guid.instance_id = tvb_get_ntohl(tvb, offset+16);
    guid.fields_present |= GUID_HAS_HOST_ID|GUID_HAS_APP_ID|GUID_HAS_INSTANCE_ID;
    /* If the packet uses TCP we need top store the participant GUID to get the domainId later
     * For that operation the member fields_present is not required and is not affected by
     * its changes.
     */
    if (pinfo->private_table == NULL && pinfo->ptype == PT_TCP) {
      pinfo->private_table = g_hash_table_new_full(g_str_hash, g_str_equal,
        g_free, g_free);
    }
    if (pinfo->private_table != NULL) {
      gchar* key = wmem_strdup(wmem_packet_scope() , RTPS_TCPMAP_DOMAIN_ID_KEY_STR);
      endpoint_guid *guid_copy = (endpoint_guid*)wmem_memdup(wmem_packet_scope(),
        (const void*)&guid, sizeof(endpoint_guid));
      g_hash_table_insert(pinfo->private_table, (gpointer)key, (gpointer)guid_copy);
    }
#ifdef RTI_BUILD
    pinfo->guid_prefix_host = tvb_get_ntohl(tvb, offset + 8);
    pinfo->guid_prefix_app  = tvb_get_ntohl(tvb, offset + 12);
    pinfo->guid_prefix_count = tvb_get_ntohl(tvb, offset + 16);
    pinfo->guid_rtps2 = 1;
#endif
  }
  /* Extract the domain id and participant index */
  {
    int domain_id, doffset, participant_idx = 0, nature;
    proto_tree *mapping_tree;
    /* For a complete description of these rules, see RTPS documentation

       RTPS 1.2 mapping:
        domain_id = ((pinfo->destport - PORT_BASE)/10) % 100;
        participant_idx = (pinfo->destport - PORT_BASE) / 1000;
        nature    = (pinfo->destport % 10);

       For Unicast, the port mapping formula is:
         metatraffic_unicast_port = port_base +
                                    (domain_id_gain * domain_id) +
                                    (participant_id_gain * participant_id) +
                                    builtin_unicast_port_offset
       For Multicast, the port mapping is:
         metatraffic_multicast_port = port_base +
                                    (domain_id_gain * domain_id) +
                                     builtin_multicast_port_offset

       Where the constants are:
            port_base = 7400
            domain_id_gain = 250
            participant_id_gain = 2
            builtin_multicast_port_offset = 0
            builtin_unicast_port_offset = 10
            user_multicast_port_offset = 1
            user_unicast_port_offset = 11


       To obtain the individual components from the port number, the reverse formulas are:
            domain_id = (port - port_base) / 250        (valid both multicast / unicast)
            Doffset = (port - port_Base - (domain_id * 250));
            participant_idx = (Doffset - 10) / 2;

    */
    if (version < 0x0200) {
      /* If using TCP domainId cannot deduced from the port. It must be taken from the participant
       * discovery packets or Unknown.
       */
      domain_id = (pinfo->ptype == PT_TCP) ?
        get_domain_id_from_tcp_discovered_participants(discovered_tcp_participants, &guid) :
        ((pinfo->destport - PORT_BASE)/10) % 100;
      participant_idx = (pinfo->destport - PORT_BASE) / 1000;
      nature    = (pinfo->destport % 10);
    } else {
      domain_id = (pinfo->ptype == PT_TCP) ?
        get_domain_id_from_tcp_discovered_participants(discovered_tcp_participants, &guid) :
        (pinfo->destport - PORT_BASE) / 250;
      doffset = (pinfo->destport - PORT_BASE - domain_id * 250);
      if (doffset == 0) {
        nature = PORT_METATRAFFIC_MULTICAST;
      } else if (doffset == 1) {
        nature = PORT_USERTRAFFIC_MULTICAST;
      } else {
        participant_idx = (doffset - 10) / 2;
        if ( (doffset - 10) % 2 == 0) {
          nature = PORT_METATRAFFIC_UNICAST;
        } else {
          nature = PORT_USERTRAFFIC_UNICAST;
        }
      }
    }
    /* Used string for the domain participant to show Unknown if the domainId is not known when using TCP*/
    if (domain_id != RTPS_UNKNOWN_DOMAIN_ID_VAL) {
      g_snprintf(domain_id_str, RTPS_UNKNOWN_DOMAIN_ID_STR_LEN,
        "%"G_GINT32_FORMAT, domain_id);
    }
    if ((nature == PORT_METATRAFFIC_UNICAST) || (nature == PORT_USERTRAFFIC_UNICAST) ||
        (version < 0x0200)) {
      mapping_tree = proto_tree_add_subtree_format(rtps_tree, tvb, 0, 0,
                        ett_rtps_default_mapping, NULL, "Default port mapping: domainId=%s, "
                        "participantIdx=%d, nature=%s",
                        domain_id_str,
                        participant_idx,
                        val_to_str(nature, nature_type_vals, "%02x"));
    } else {
      mapping_tree = proto_tree_add_subtree_format(rtps_tree, tvb, 0, 0,
                        ett_rtps_default_mapping, NULL, "Default port mapping: %s, domainId=%s",
                        val_to_str(nature, nature_type_vals, "%02x"),
                        domain_id_str);
    }

    ti = proto_tree_add_uint(mapping_tree, hf_rtps_domain_id, tvb, 0, 0, domain_id);
    proto_item_set_generated(ti);
    if ((nature == PORT_METATRAFFIC_UNICAST) || (nature == PORT_USERTRAFFIC_UNICAST) ||
        (version < 0x0200)) {
      ti = proto_tree_add_uint(mapping_tree, hf_rtps_participant_idx, tvb, 0, 0, participant_idx);
      proto_item_set_generated(ti);
    }
    ti = proto_tree_add_uint(mapping_tree, hf_rtps_nature_type, tvb, 0, 0, nature);
    proto_item_set_generated(ti);
  }

  /* offset behind RTPS's Header (need to be set in case tree=NULL)*/
  offset += ((version < 0x0200) ? 16 : 20);

  while (tvb_reported_length_remaining(tvb, offset) > 0) {
    submessageId = tvb_get_guint8(tvb, offset);

    if (version < 0x0200) {
      sub_hf = hf_rtps_sm_id;
      sub_vals = submessage_id_vals;
    } else {
      if ((submessageId & 0x80) && (vendor_id == RTPS_VENDOR_RTI_DDS)) {
        sub_hf = hf_rtps_sm_idv2;
        sub_vals = submessage_id_rti;
      } else {
        sub_hf = hf_rtps_sm_idv2;
        sub_vals = submessage_id_valsv2;
      }
    }

    col_append_sep_str(pinfo->cinfo, COL_INFO, ", ", val_to_str(submessageId, sub_vals, "Unknown[%02x]"));

    /* Creates the subtree 'Submessage: XXXX' */
    if (submessageId & 0x80) {
      if (vendor_id == RTPS_VENDOR_RTI_DDS) {
        ti = proto_tree_add_uint_format_value(rtps_tree, sub_hf, tvb, offset, 1, submessageId, "%s",
                val_to_str(submessageId, submessage_id_rti, "Vendor-specific (0x%02x)"));
      } else {
        ti = proto_tree_add_uint_format_value(rtps_tree, sub_hf, tvb, offset, 1,
                submessageId, "Vendor-specific (0x%02x)", submessageId);
      }
    } else {
      ti = proto_tree_add_uint(rtps_tree, sub_hf, tvb, offset, 1, submessageId);
    }

    rtps_submessage_tree = proto_item_add_subtree(ti, ett_rtps_submessage);

    /* Gets the flags */
    flags = tvb_get_guint8(tvb, offset + 1);

    /* Gets the E (Little endian) flag */
    encoding = ((flags & FLAG_E) != 0) ? ENC_LITTLE_ENDIAN : ENC_BIG_ENDIAN;

    /* Octets-to-next-header */
    octets_to_next_header = tvb_get_guint16(tvb, offset + 2, encoding);
    if ((octets_to_next_header == 0) && (version >= 0x0200) && (submessageId != SUBMESSAGE_PAD) && (submessageId != SUBMESSAGE_INFO_TS)) {
      octets_to_next_header = tvb_reported_length_remaining(tvb, offset + 4);
    }
    next_submsg = offset + octets_to_next_header + 4;

    /* Set length of this item */
    proto_item_set_len(ti, octets_to_next_header + 4);

    /* Now decode each single submessage
     * The offset passed to the dissectors points to the start of the
     * submessage (at the ID byte).
     */
    if (!dissect_rtps_submessage_v1(tvb, pinfo, offset, flags, encoding,
                                    submessageId, version, vendor_id,
                                    octets_to_next_header, rtps_submessage_tree,
                                    ti, &guid, &dst_guid)) {
      if ((version < 0x0200) ||
          !dissect_rtps_submessage_v2(tvb, pinfo, offset, flags, encoding, submessageId,
                                      vendor_id, octets_to_next_header, rtps_submessage_tree,
                                      ti, &guid, &dst_guid)) {
        proto_tree_add_uint(rtps_submessage_tree, hf_rtps_sm_flags,
                              tvb, offset + 1, 1, flags);
        proto_tree_add_uint(rtps_submessage_tree,
                                hf_rtps_sm_octets_to_next_header,
                                tvb, offset + 2, 2, octets_to_next_header);
      }
    }

     /* next submessage's offset */
     offset = next_submsg;
  }

  /* If TCP there's an extra OOB byte at the end of the message */
  /* TODO: What to do with it? */
  return TRUE;

}  /* dissect_rtps(...) */

static int do_uncompress_block(struct archive_read* a, const uint8_t* p) {
    struct rar5* rar = get_context(a);
    uint16_t num;
    int ret;

    const int cmask = rar->cstate.window_mask;
    const struct compressed_block_header* hdr = &rar->last_block_hdr;
    const uint8_t bit_size = 1 + bf_bit_size(hdr);

    while(1) {
        if(rar->cstate.write_ptr - rar->cstate.last_write_ptr >
                (rar->cstate.window_size >> 1)) {

            /* Don't allow growing data by more than half of the window size
             * at a time. In such case, break the loop; next call to this
             * function will continue processing from this moment. */

            break;
        }

        if(rar->bits.in_addr > rar->cstate.cur_block_size - 1 ||
                (rar->bits.in_addr == rar->cstate.cur_block_size - 1 &&
                 rar->bits.bit_addr >= bit_size))
        {
            /* If the program counter is here, it means the function has
             * finished processing the block. */
            rar->cstate.block_parsing_finished = 1;
            break;
        }

        /* Decode the next literal. */
        if(ARCHIVE_OK != decode_number(a, &rar->cstate.ld, p, &num)) {
            return ARCHIVE_EOF;
        }

        /* Num holds a decompression literal, or 'command code'.
         *
         * - Values lower than 256 are just bytes. Those codes can be stored
         *   in the output buffer directly.
         *
         * - Code 256 defines a new filter, which is later used to transform
         *   the data block accordingly to the filter type. The data block
         *   needs to be fully uncompressed first.
         *
         * - Code bigger than 257 and smaller than 262 define a repetition
         *   pattern that should be copied from an already uncompressed chunk
         *   of data.
         */

        if(num < 256) {
            /* Directly store the byte. */

            int64_t write_idx = rar->cstate.solid_offset +
                rar->cstate.write_ptr++;

            rar->cstate.window_buf[write_idx & cmask] = (uint8_t) num;
            continue;
        } else if(num >= 262) {
            uint16_t dist_slot;
            int len = decode_code_length(rar, p, num - 262),
                dbits,
                dist = 1;

            if(len == -1) {
                archive_set_error(&a->archive, ARCHIVE_ERRNO_PROGRAMMER,
                    "Failed to decode the code length");

                return ARCHIVE_FATAL;
            }

            if(ARCHIVE_OK != decode_number(a, &rar->cstate.dd, p, &dist_slot))
            {
                archive_set_error(&a->archive, ARCHIVE_ERRNO_PROGRAMMER,
                    "Failed to decode the distance slot");

                return ARCHIVE_FATAL;
            }

            if(dist_slot < 4) {
                dbits = 0;
                dist += dist_slot;
            } else {
                dbits = dist_slot / 2 - 1;
                dist += (2 | (dist_slot & 1)) << dbits;
            }

            if(dbits > 0) {
                if(dbits >= 4) {
                    uint32_t add = 0;
                    uint16_t low_dist;

                    if(dbits > 4) {
                        if(ARCHIVE_OK != read_bits_32(rar, p, &add)) {
                            /* Return EOF if we can't read more data. */
                            return ARCHIVE_EOF;
                        }

                        skip_bits(rar, dbits - 4);
                        add = (add >> (36 - dbits)) << 4;
                        dist += add;
                    }

                    if(ARCHIVE_OK != decode_number(a, &rar->cstate.ldd, p,
                                &low_dist))
                    {
                        archive_set_error(&a->archive,
                                ARCHIVE_ERRNO_PROGRAMMER,
                                "Failed to decode the distance slot");

                        return ARCHIVE_FATAL;
                    }

                    dist += low_dist;
                } else {
                    /* dbits is one of [0,1,2,3] */
                    int add;

                    if(ARCHIVE_OK != read_consume_bits(rar, p, dbits, &add)) {
                        /* Return EOF if we can't read more data. */
                        return ARCHIVE_EOF;
                    }

                    dist += add;
                }
            }

            if(dist > 0x100) {
                len++;

                if(dist > 0x2000) {
                    len++;

                    if(dist > 0x40000) {
                        len++;
                    }
                }
            }

            dist_cache_push(rar, dist);
            rar->cstate.last_len = len;

            if(ARCHIVE_OK != copy_string(a, len, dist))
                return ARCHIVE_FATAL;

            continue;
        } else if(num == 256) {
            /* Create a filter. */
            ret = parse_filter(a, p);
            if(ret != ARCHIVE_OK)
                return ret;

            continue;
        } else if(num == 257) {
            if(rar->cstate.last_len != 0) {
                if(ARCHIVE_OK != copy_string(a, rar->cstate.last_len,
                            rar->cstate.dist_cache[0]))
                {
                    return ARCHIVE_FATAL;
                }
            }

            continue;
        } else if(num < 262) {
            const int idx = num - 258;
            const int dist = dist_cache_touch(rar, idx);

            uint16_t len_slot;
            int len;

            if(ARCHIVE_OK != decode_number(a, &rar->cstate.rd, p, &len_slot)) {
                return ARCHIVE_FATAL;
            }

            len = decode_code_length(rar, p, len_slot);
            rar->cstate.last_len = len;

            if(ARCHIVE_OK != copy_string(a, len, dist))
                return ARCHIVE_FATAL;

            continue;
        }

        /* The program counter shouldn't reach here. */
        archive_set_error(&a->archive, ARCHIVE_ERRNO_FILE_FORMAT,
                "Unsupported block code: 0x%02x", num);

        return ARCHIVE_FATAL;
    }

static unsigned char *
kex_agree_instr(unsigned char *haystack, unsigned long haystack_len,
                const unsigned char *needle, unsigned long needle_len)
{
    unsigned char *s;

    /* Haystack too short to bother trying */
    if(haystack_len < needle_len) {
        return NULL;
    }

    /* Needle at start of haystack */
    if((strncmp((char *) haystack, (char *) needle, needle_len) == 0) &&
        (needle_len == haystack_len || haystack[needle_len] == ',')) {
        return haystack;
    }

    s = haystack;
    /* Search until we run out of comas or we run out of haystack,
       whichever comes first */
    while((s = (unsigned char *) strchr((char *) s, ','))
           && ((haystack_len - (s - haystack)) > needle_len)) {
        s++;
        /* Needle at X position */
        if((strncmp((char *) s, (char *) needle, needle_len) == 0) &&
            (((s - haystack) + needle_len) == haystack_len
             || s[needle_len] == ',')) {
            return s;
        }
    }

    return NULL;
}

int
ares_parse_soa_reply(const unsigned char *abuf, int alen,
		     struct ares_soa_reply **soa_out)
{
  const unsigned char *aptr;
  long len;
  char *qname = NULL, *rr_name = NULL;
  struct ares_soa_reply *soa = NULL;
  int qdcount, ancount, qclass;
  int status, i, rr_type, rr_class, rr_len;

  if (alen < HFIXEDSZ)
    return ARES_EBADRESP;

  /* parse message header */
  qdcount = DNS_HEADER_QDCOUNT(abuf);
  ancount = DNS_HEADER_ANCOUNT(abuf);

  if (qdcount != 1)
    return ARES_EBADRESP;
  if (ancount == 0)
    return ARES_EBADRESP;

  aptr = abuf + HFIXEDSZ;

  /* query name */
  status = ares__expand_name_for_response(aptr, abuf, alen, &qname, &len);
  if (status != ARES_SUCCESS)
    goto failed_stat;
  aptr += len;

  qclass = DNS_QUESTION_TYPE(aptr);

  /* skip qtype & qclass */
  if (aptr + QFIXEDSZ > abuf + alen)
    goto failed;
  aptr += QFIXEDSZ;

  /* qclass of SOA with multiple answers */
  if (qclass == T_SOA && ancount > 1)
    goto failed;

  /* examine all the records, break and return if found soa */
  for (i = 0; i < ancount; i++)
  {
    status = ares__expand_name_for_response (aptr, abuf, alen, &rr_name, &len);
    if (status != ARES_SUCCESS)
     {
      ares_free(rr_name);
      goto failed_stat;
     }

    aptr += len;
    if ( aptr + RRFIXEDSZ > abuf + alen )
    {
      ares_free(rr_name);
      status = ARES_EBADRESP;
      goto failed_stat;
    }
    rr_type = DNS_RR_TYPE( aptr );
    rr_class = DNS_RR_CLASS( aptr );
    rr_len = DNS_RR_LEN( aptr );
    aptr += RRFIXEDSZ;
    if (aptr + rr_len > abuf + alen)
      {
        ares_free(rr_name);
        status = ARES_EBADRESP;
        goto failed_stat;
      }
    if ( rr_class == C_IN && rr_type == T_SOA )
    {
      /* allocate result struct */
      soa = ares_malloc_data(ARES_DATATYPE_SOA_REPLY);
      if (!soa)
        {
          ares_free(rr_name);
          status = ARES_ENOMEM;
          goto failed_stat;
        }

      /* nsname */
      status = ares__expand_name_for_response(aptr, abuf, alen, &soa->nsname,
                                               &len);
      if (status != ARES_SUCCESS)
       {
        ares_free(rr_name);
        goto failed_stat;
       }
      aptr += len;

      /* hostmaster */
      status = ares__expand_name_for_response(aptr, abuf, alen,
                                               &soa->hostmaster, &len);
      if (status != ARES_SUCCESS)
       {
        ares_free(rr_name);
        goto failed_stat;
       }
      aptr += len;

      /* integer fields */
      if (aptr + 5 * 4 > abuf + alen)
       {
        ares_free(rr_name);
        goto failed;
       }
      soa->serial = DNS__32BIT(aptr + 0 * 4);
      soa->refresh = DNS__32BIT(aptr + 1 * 4);
      soa->retry = DNS__32BIT(aptr + 2 * 4);
      soa->expire = DNS__32BIT(aptr + 3 * 4);
      soa->minttl = DNS__32BIT(aptr + 4 * 4);

      ares_free(qname);
      ares_free(rr_name);

      *soa_out = soa;

      return ARES_SUCCESS;
    }
    aptr += rr_len;

    ares_free(rr_name);

    if (aptr > abuf + alen)
      goto failed_stat;
  }
  /* no SOA record found */
  status = ARES_EBADRESP;
  goto failed_stat;
failed:
  status = ARES_EBADRESP;

failed_stat:
  if (soa)
    ares_free_data(soa);
  if (qname)
    ares_free(qname);
  return status;
}

struct json_object *json_tokener_parse_ex(struct json_tokener *tok, const char *str, int len)
{
    struct json_object *obj = NULL;
    char c = '\1';
    unsigned int nBytes = 0;
    unsigned int *nBytesp = &nBytes;

#ifdef HAVE_USELOCALE
    locale_t oldlocale = uselocale(NULL);
    locale_t newloc;
#elif defined(HAVE_SETLOCALE)
    char *oldlocale = NULL;
#endif

    tok->char_offset = 0;
    tok->err = json_tokener_success;

    /* this interface is presently not 64-bit clean due to the int len argument
     * and the internal printbuf interface that takes 32-bit int len arguments
     * so the function limits the maximum string size to INT32_MAX (2GB).
     * If the function is called with len == -1 then strlen is called to check
     * the string length is less than INT32_MAX (2GB)
     */
    if ((len < -1) || (len == -1 && strlen(str) > INT32_MAX))
    {
        tok->err = json_tokener_error_size;
        return NULL;
    }

#ifdef HAVE_USELOCALE
    {
        locale_t duploc = duplocale(oldlocale);
        newloc = newlocale(LC_NUMERIC_MASK, "C", duploc);
        if (newloc == NULL)
        {
            freelocale(duploc);
            return NULL;
        }
        uselocale(newloc);
    }
#elif defined(HAVE_SETLOCALE)
    {
        char *tmplocale;
        tmplocale = setlocale(LC_NUMERIC, NULL);
        if (tmplocale)
            oldlocale = strdup(tmplocale);
        setlocale(LC_NUMERIC, "C");
    }
#endif

    while (PEEK_CHAR(c, tok))
    {

    redo_char:
        switch (state)
        {

        case json_tokener_state_eatws:
            /* Advance until we change state */
            while (isspace((unsigned char)c))
            {
                if ((!ADVANCE_CHAR(str, tok)) || (!PEEK_CHAR(c, tok)))
                    goto out;
            }
            if (c == '/' && !(tok->flags & JSON_TOKENER_STRICT))
            {
                printbuf_reset(tok->pb);
                printbuf_memappend_fast(tok->pb, &c, 1);
                state = json_tokener_state_comment_start;
            }
            else
            {
                state = saved_state;
                goto redo_char;
            }
            break;

        case json_tokener_state_start:
            switch (c)
            {
            case '{':
                state = json_tokener_state_eatws;
                saved_state = json_tokener_state_object_field_start;
                current = json_object_new_object();
                if (current == NULL)
                    goto out;
                break;
            case '[':
                state = json_tokener_state_eatws;
                saved_state = json_tokener_state_array;
                current = json_object_new_array();
                if (current == NULL)
                    goto out;
                break;
            case 'I':
            case 'i':
                state = json_tokener_state_inf;
                printbuf_reset(tok->pb);
                tok->st_pos = 0;
                goto redo_char;
            case 'N':
            case 'n':
                state = json_tokener_state_null; // or NaN
                printbuf_reset(tok->pb);
                tok->st_pos = 0;
                goto redo_char;
            case '\'':
                if (tok->flags & JSON_TOKENER_STRICT)
                {
                    /* in STRICT mode only double-quote are allowed */
                    tok->err = json_tokener_error_parse_unexpected;
                    goto out;
                }
                /* FALLTHRU */
            case '\"':
                state = json_tokener_state_string;
                printbuf_reset(tok->pb);
                tok->quote_char = c;
                break;
            case 'T':
            case 't':
            case 'F':
            case 'f':
                state = json_tokener_state_boolean;
                printbuf_reset(tok->pb);
                tok->st_pos = 0;
                goto redo_char;
            case '0':
            case '1':
            case '2':
            case '3':
            case '4':
            case '5':
            case '6':
            case '7':
            case '8':
            case '9':
            case '-':
                state = json_tokener_state_number;
                printbuf_reset(tok->pb);
                tok->is_double = 0;
                goto redo_char;
            default: tok->err = json_tokener_error_parse_unexpected; goto out;
            }
            break;

        case json_tokener_state_finish:
            if (tok->depth == 0)
                goto out;
            obj = json_object_get(current);
            json_tokener_reset_level(tok, tok->depth);
            tok->depth--;
            goto redo_char;

        case json_tokener_state_inf: /* aka starts with 'i' (or 'I', or "-i", or "-I") */
        {
            /* If we were guaranteed to have len set, then we could (usually) handle
             * the entire "Infinity" check in a single strncmp (strncasecmp), but
             * since len might be -1 (i.e. "read until \0"), we need to check it
             * a character at a time.
             * Trying to handle it both ways would make this code considerably more
             * complicated with likely little performance benefit.
             */
            int is_negative = 0;
            const char *_json_inf_str = json_inf_str;
            if (!(tok->flags & JSON_TOKENER_STRICT))
                _json_inf_str = json_inf_str_lower;

            /* Note: tok->st_pos must be 0 when state is set to json_tokener_state_inf */
            while (tok->st_pos < (int)json_inf_str_len)
            {
                char inf_char = *str;
                if (!(tok->flags & JSON_TOKENER_STRICT))
                    inf_char = tolower((int)*str);
                if (inf_char != _json_inf_str[tok->st_pos])
                {
                    tok->err = json_tokener_error_parse_unexpected;
                    goto out;
                }
                tok->st_pos++;
                (void)ADVANCE_CHAR(str, tok);
                if (!PEEK_CHAR(c, tok))
                {
                    /* out of input chars, for now at least */
                    goto out;
                }
            }
            /* We checked the full length of "Infinity", so create the object.
             * When handling -Infinity, the number parsing code will have dropped
             * the "-" into tok->pb for us, so check it now.
             */
            if (printbuf_length(tok->pb) > 0 && *(tok->pb->buf) == '-')
            {
                is_negative = 1;
            }
            current = json_object_new_double(is_negative ? -INFINITY : INFINITY);
            if (current == NULL)
                goto out;
            saved_state = json_tokener_state_finish;
            state = json_tokener_state_eatws;
            goto redo_char;
        }
        break;
        case json_tokener_state_null: /* aka starts with 'n' */
        {
            int size;
            int size_nan;
            printbuf_memappend_fast(tok->pb, &c, 1);
            size = json_min(tok->st_pos + 1, json_null_str_len);
            size_nan = json_min(tok->st_pos + 1, json_nan_str_len);
            if ((!(tok->flags & JSON_TOKENER_STRICT) &&
                 strncasecmp(json_null_str, tok->pb->buf, size) == 0) ||
                (strncmp(json_null_str, tok->pb->buf, size) == 0))
            {
                if (tok->st_pos == json_null_str_len)
                {
                    current = NULL;
                    saved_state = json_tokener_state_finish;
                    state = json_tokener_state_eatws;
                    goto redo_char;
                }
            }
            else if ((!(tok->flags & JSON_TOKENER_STRICT) &&
                      strncasecmp(json_nan_str, tok->pb->buf, size_nan) == 0) ||
                     (strncmp(json_nan_str, tok->pb->buf, size_nan) == 0))
            {
                if (tok->st_pos == json_nan_str_len)
                {
                    current = json_object_new_double(NAN);
                    if (current == NULL)
                        goto out;
                    saved_state = json_tokener_state_finish;
                    state = json_tokener_state_eatws;
                    goto redo_char;
                }
            }
            else
            {
                tok->err = json_tokener_error_parse_null;
                goto out;
            }
            tok->st_pos++;
        }
        break;

        case json_tokener_state_comment_start:
            if (c == '*')
            {
                state = json_tokener_state_comment;
            }
            else if (c == '/')
            {
                state = json_tokener_state_comment_eol;
            }
            else
            {
                tok->err = json_tokener_error_parse_comment;
                goto out;
            }
            printbuf_memappend_fast(tok->pb, &c, 1);
            break;

        case json_tokener_state_comment:
        {
            /* Advance until we change state */
            const char *case_start = str;
            while (c != '*')
            {
                if (!ADVANCE_CHAR(str, tok) || !PEEK_CHAR(c, tok))
                {
                    printbuf_memappend_fast(tok->pb, case_start,
                                            str - case_start);
                    goto out;
                }
            }
            printbuf_memappend_fast(tok->pb, case_start, 1 + str - case_start);
            state = json_tokener_state_comment_end;
        }
        break;

        case json_tokener_state_comment_eol:
        {
            /* Advance until we change state */
            const char *case_start = str;
            while (c != '\n')
            {
                if (!ADVANCE_CHAR(str, tok) || !PEEK_CHAR(c, tok))
                {
                    printbuf_memappend_fast(tok->pb, case_start,
                                            str - case_start);
                    goto out;
                }
            }
            printbuf_memappend_fast(tok->pb, case_start, str - case_start);
            MC_DEBUG("json_tokener_comment: %s\n", tok->pb->buf);
            state = json_tokener_state_eatws;
        }
        break;

        case json_tokener_state_comment_end:
            printbuf_memappend_fast(tok->pb, &c, 1);
            if (c == '/')
            {
                MC_DEBUG("json_tokener_comment: %s\n", tok->pb->buf);
                state = json_tokener_state_eatws;
            }
            else
            {
                state = json_tokener_state_comment;
            }
            break;

        case json_tokener_state_string:
        {
            /* Advance until we change state */
            const char *case_start = str;
            while (1)
            {
                if (c == tok->quote_char)
                {
                    printbuf_memappend_fast(tok->pb, case_start,
                                            str - case_start);
                    current =
                        json_object_new_string_len(tok->pb->buf, tok->pb->bpos);
                    if (current == NULL)
                        goto out;
                    saved_state = json_tokener_state_finish;
                    state = json_tokener_state_eatws;
                    break;
                }
                else if (c == '\\')
                {
                    printbuf_memappend_fast(tok->pb, case_start,
                                            str - case_start);
                    saved_state = json_tokener_state_string;
                    state = json_tokener_state_string_escape;
                    break;
                }
                if (!ADVANCE_CHAR(str, tok) || !PEEK_CHAR(c, tok))
                {
                    printbuf_memappend_fast(tok->pb, case_start,
                                            str - case_start);
                    goto out;
                }
            }
        }
        break;

        case json_tokener_state_string_escape:
            switch (c)
            {
            case '\"':
            case '\\':
            case '/':
                printbuf_memappend_fast(tok->pb, &c, 1);
                state = saved_state;
                break;
            case 'b':
            case 'n':
            case 'r':
            case 't':
            case 'f':
                if (c == 'b')
                    printbuf_memappend_fast(tok->pb, "\b", 1);
                else if (c == 'n')
                    printbuf_memappend_fast(tok->pb, "\n", 1);
                else if (c == 'r')
                    printbuf_memappend_fast(tok->pb, "\r", 1);
                else if (c == 't')
                    printbuf_memappend_fast(tok->pb, "\t", 1);
                else if (c == 'f')
                    printbuf_memappend_fast(tok->pb, "\f", 1);
                state = saved_state;
                break;
            case 'u':
                tok->ucs_char = 0;
                tok->st_pos = 0;
                state = json_tokener_state_escape_unicode;
                break;
            default: tok->err = json_tokener_error_parse_string; goto out;
            }
            break;

        case json_tokener_state_escape_unicode:
        {
            /* Handle a 4-byte sequence, or two sequences if a surrogate pair */
            while (1)
            {
                if (c && strchr(json_hex_chars, c))
                {
                    tok->ucs_char += ((unsigned int)jt_hexdigit(c)
                                      << ((3 - tok->st_pos++) * 4));
                    if (tok->st_pos == 4)
                    {
                        unsigned char unescaped_utf[4];

                        if (tok->got_hi_surrogate)
                        {
                            if (IS_LOW_SURROGATE(tok->ucs_char))
                            {
                                /* remove the utf8_replacement_char */
                                /* which may generate during */
                                /* parsing the high surrogate pair. */
                                if (!strcmp(
                                        tok->pb->buf,
                                        (char *)
                                            utf8_replacement_char))
                                {
                                    printbuf_reset(tok->pb);
                                }
                                /* Recalculate the ucs_char, then fall thru to process normally */
                                tok->ucs_char =
                                    DECODE_SURROGATE_PAIR(
                                        tok->got_hi_surrogate,
                                        tok->ucs_char);
                            }
                            else
                            {
                                /* Hi surrogate was not followed by a low surrogate */
                                /* Replace the hi and process the rest normally */
                                printbuf_memappend_fast(
                                    tok->pb,
                                    (char *)utf8_replacement_char,
                                    3);
                            }
                            tok->got_hi_surrogate = 0;
                        }

                        if (tok->ucs_char < 0x80)
                        {
                            unescaped_utf[0] = tok->ucs_char;
                            printbuf_memappend_fast(
                                tok->pb, (char *)unescaped_utf, 1);
                        }
                        else if (tok->ucs_char < 0x800)
                        {
                            unescaped_utf[0] =
                                0xc0 | (tok->ucs_char >> 6);
                            unescaped_utf[1] =
                                0x80 | (tok->ucs_char & 0x3f);
                            printbuf_memappend_fast(
                                tok->pb, (char *)unescaped_utf, 2);
                        }
                        else if (IS_HIGH_SURROGATE(tok->ucs_char))
                        {
                            /* Got a high surrogate.  Remember it and look for
                             * the beginning of another sequence, which
                             * should be the low surrogate.
                             */
                            tok->got_hi_surrogate = tok->ucs_char;
                            /* Not at end, and the next two chars should be "\u" */
                            if ((len == -1 ||
                                 len > (tok->char_offset + 2)) &&
                                // str[0] != '0' &&  // implied by json_hex_chars, above.
                                (str[1] == '\\') && (str[2] == 'u'))
                            {
                                /* Advance through the 16 bit surrogate, and move
                                 * on to the next sequence. The next step is to
                                 * process the following characters.
                                 */
                                if (!ADVANCE_CHAR(str, tok) ||
                                    !ADVANCE_CHAR(str, tok))
                                {
                                    printbuf_memappend_fast(
                                        tok->pb,
                                        (char *)
                                            utf8_replacement_char,
                                        3);
                                }
                                /* Advance to the first char of the next sequence and
                                 * continue processing with the next sequence.
                                 */
                                if (!ADVANCE_CHAR(str, tok) ||
                                    !PEEK_CHAR(c, tok))
                                {
                                    printbuf_memappend_fast(
                                        tok->pb,
                                        (char *)
                                            utf8_replacement_char,
                                        3);
                                    tok->ucs_char = 0;
                                    tok->st_pos = 0;
                                    goto out;
                                }
                                tok->ucs_char = 0;
                                tok->st_pos = 0;
                                /* other json_tokener_state_escape_unicode */
                                continue;
                            }
                            else
                            {
                                /* Got a high surrogate without another sequence following
                                 * it.  Put a replacement char in for the hi surrogate
                                 * and pretend we finished.
                                 */
                                printbuf_memappend_fast(
                                    tok->pb,
                                    (char *)utf8_replacement_char,
                                    3);
                            }
                        }
                        else if (IS_LOW_SURROGATE(tok->ucs_char))
                        {
                            /* Got a low surrogate not preceded by a high */
                            printbuf_memappend_fast(
                                tok->pb, (char *)utf8_replacement_char,
                                3);
                        }
                        else if (tok->ucs_char < 0x10000)
                        {
                            unescaped_utf[0] =
                                0xe0 | (tok->ucs_char >> 12);
                            unescaped_utf[1] =
                                0x80 | ((tok->ucs_char >> 6) & 0x3f);
                            unescaped_utf[2] =
                                0x80 | (tok->ucs_char & 0x3f);
                            printbuf_memappend_fast(
                                tok->pb, (char *)unescaped_utf, 3);
                        }
                        else if (tok->ucs_char < 0x110000)
                        {
                            unescaped_utf[0] =
                                0xf0 | ((tok->ucs_char >> 18) & 0x07);
                            unescaped_utf[1] =
                                0x80 | ((tok->ucs_char >> 12) & 0x3f);
                            unescaped_utf[2] =
                                0x80 | ((tok->ucs_char >> 6) & 0x3f);
                            unescaped_utf[3] =
                                0x80 | (tok->ucs_char & 0x3f);
                            printbuf_memappend_fast(
                                tok->pb, (char *)unescaped_utf, 4);
                        }
                        else
                        {
                            /* Don't know what we got--insert the replacement char */
                            printbuf_memappend_fast(
                                tok->pb, (char *)utf8_replacement_char,
                                3);
                        }
                        state = saved_state;
                        break;
                    }
                }
                else
                {
                    tok->err = json_tokener_error_parse_string;
                    goto out;
                }
                if (!ADVANCE_CHAR(str, tok) || !PEEK_CHAR(c, tok))
                {
                    /* Clean up any pending chars */
                    if (tok->got_hi_surrogate &&
                        strcmp(tok->pb->buf, (char *)utf8_replacement_char))
                        printbuf_memappend_fast(
                            tok->pb, (char *)utf8_replacement_char, 3);
                    goto out;
                }
            }
        }
        break;

        case json_tokener_state_boolean:
        {
            int size1, size2;
            printbuf_memappend_fast(tok->pb, &c, 1);
            size1 = json_min(tok->st_pos + 1, json_true_str_len);
            size2 = json_min(tok->st_pos + 1, json_false_str_len);
            if ((!(tok->flags & JSON_TOKENER_STRICT) &&
                 strncasecmp(json_true_str, tok->pb->buf, size1) == 0) ||
                (strncmp(json_true_str, tok->pb->buf, size1) == 0))
            {
                if (tok->st_pos == json_true_str_len)
                {
                    current = json_object_new_boolean(1);
                    if (current == NULL)
                        goto out;
                    saved_state = json_tokener_state_finish;
                    state = json_tokener_state_eatws;
                    goto redo_char;
                }
            }
            else if ((!(tok->flags & JSON_TOKENER_STRICT) &&
                      strncasecmp(json_false_str, tok->pb->buf, size2) == 0) ||
                     (strncmp(json_false_str, tok->pb->buf, size2) == 0))
            {
                if (tok->st_pos == json_false_str_len)
                {
                    current = json_object_new_boolean(0);
                    if (current == NULL)
                        goto out;
                    saved_state = json_tokener_state_finish;
                    state = json_tokener_state_eatws;
                    goto redo_char;
                }
            }
            else
            {
                tok->err = json_tokener_error_parse_boolean;
                goto out;
            }
            tok->st_pos++;
        }
        break;

        case json_tokener_state_number:
        {
            /* Advance until we change state */
            const char *case_start = str;
            int case_len = 0;
            int is_exponent = 0;
            int negativesign_next_possible_location = 1;
            while (c && strchr(json_number_chars, c))
            {
                ++case_len;

                /* non-digit characters checks */
                /* note: since the main loop condition to get here was
                 * an input starting with 0-9 or '-', we are
                 * protected from input starting with '.' or
                 * e/E.
                 */
                if (c == '.')
                {
                    if (tok->is_double != 0)
                    {
                        /* '.' can only be found once, and out of the exponent part.
                         * Thus, if the input is already flagged as double, it
                         * is invalid.
                         */
                        tok->err = json_tokener_error_parse_number;
                        goto out;
                    }
                    tok->is_double = 1;
                }
                if (c == 'e' || c == 'E')
                {
                    if (is_exponent != 0)
                    {
                        /* only one exponent possible */
                        tok->err = json_tokener_error_parse_number;
                        goto out;
                    }
                    is_exponent = 1;
                    tok->is_double = 1;
                    /* the exponent part can begin with a negative sign */
                    negativesign_next_possible_location = case_len + 1;
                }
                if (c == '-' && case_len != negativesign_next_possible_location)
                {
                    /* If the negative sign is not where expected (ie
                     * start of input or start of exponent part), the
                     * input is invalid.
                     */
                    tok->err = json_tokener_error_parse_number;
                    goto out;
                }

                if (!ADVANCE_CHAR(str, tok) || !PEEK_CHAR(c, tok))
                {
                    printbuf_memappend_fast(tok->pb, case_start, case_len);
                    goto out;
                }
            }
            if (case_len > 0)
                printbuf_memappend_fast(tok->pb, case_start, case_len);

            // Check for -Infinity
            if (tok->pb->buf[0] == '-' && case_len <= 1 && (c == 'i' || c == 'I'))
            {
                state = json_tokener_state_inf;
                tok->st_pos = 0;
                goto redo_char;
            }
        }
            {
                int64_t num64;
                uint64_t numuint64;
                double numd;
                if (!tok->is_double && tok->pb->buf[0] == '-' &&
                    json_parse_int64(tok->pb->buf, &num64) == 0)
                {
                    current = json_object_new_int64(num64);
                    if (current == NULL)
                        goto out;
                }
                else if (!tok->is_double && tok->pb->buf[0] != '-' &&
                         json_parse_uint64(tok->pb->buf, &numuint64) == 0)
                {
                    if (numuint64 && tok->pb->buf[0] == '0' &&
                        (tok->flags & JSON_TOKENER_STRICT))
                    {
                        tok->err = json_tokener_error_parse_number;
                        goto out;
                    }
                    if (numuint64 <= INT64_MAX)
                    {
                        num64 = (uint64_t)numuint64;
                        current = json_object_new_int64(num64);
                        if (current == NULL)
                            goto out;
                    }
                    else
                    {
                        current = json_object_new_uint64(numuint64);
                        if (current == NULL)
                            goto out;
                    }
                }
                else if (tok->is_double &&
                         json_parse_double(tok->pb->buf, &numd) == 0)
                {
                    current = json_object_new_double_s(numd, tok->pb->buf);
                    if (current == NULL)
                        goto out;
                }
                else
                {
                    tok->err = json_tokener_error_parse_number;
                    goto out;
                }
                saved_state = json_tokener_state_finish;
                state = json_tokener_state_eatws;
                goto redo_char;
            }
            break;

        case json_tokener_state_array_after_sep:
        case json_tokener_state_array:
            if (c == ']')
            {
                // Minimize memory usage; assume parsed objs are unlikely to be changed
                json_object_array_shrink(current, 0);

                if (state == json_tokener_state_array_after_sep &&
                    (tok->flags & JSON_TOKENER_STRICT))
                {
                    tok->err = json_tokener_error_parse_unexpected;
                    goto out;
                }
                saved_state = json_tokener_state_finish;
                state = json_tokener_state_eatws;
            }
            else
            {
                if (tok->depth >= tok->max_depth - 1)
                {
                    tok->err = json_tokener_error_depth;
                    goto out;
                }
                state = json_tokener_state_array_add;
                tok->depth++;
                json_tokener_reset_level(tok, tok->depth);
                goto redo_char;
            }
            break;

        case json_tokener_state_array_add:
            if (json_object_array_add(current, obj) != 0)
                goto out;
            saved_state = json_tokener_state_array_sep;
            state = json_tokener_state_eatws;
            goto redo_char;

        case json_tokener_state_array_sep:
            if (c == ']')
            {
                // Minimize memory usage; assume parsed objs are unlikely to be changed
                json_object_array_shrink(current, 0);

                saved_state = json_tokener_state_finish;
                state = json_tokener_state_eatws;
            }
            else if (c == ',')
            {
                saved_state = json_tokener_state_array_after_sep;
                state = json_tokener_state_eatws;
            }
            else
            {
                tok->err = json_tokener_error_parse_array;
                goto out;
            }
            break;

        case json_tokener_state_object_field_start:
        case json_tokener_state_object_field_start_after_sep:
            if (c == '}')
            {
                if (state == json_tokener_state_object_field_start_after_sep &&
                    (tok->flags & JSON_TOKENER_STRICT))
                {
                    tok->err = json_tokener_error_parse_unexpected;
                    goto out;
                }
                saved_state = json_tokener_state_finish;
                state = json_tokener_state_eatws;
            }
            else if (c == '\"' || c == '\'')
            {
                tok->quote_char = c;
                printbuf_reset(tok->pb);
                state = json_tokener_state_object_field;
            }
            else
            {
                tok->err = json_tokener_error_parse_object_key_name;
                goto out;
            }
            break;

        case json_tokener_state_object_field:
        {
            /* Advance until we change state */
            const char *case_start = str;
            while (1)
            {
                if (c == tok->quote_char)
                {
                    printbuf_memappend_fast(tok->pb, case_start,
                                            str - case_start);
                    obj_field_name = strdup(tok->pb->buf);
                    saved_state = json_tokener_state_object_field_end;
                    state = json_tokener_state_eatws;
                    break;
                }
                else if (c == '\\')
                {
                    printbuf_memappend_fast(tok->pb, case_start,
                                            str - case_start);
                    saved_state = json_tokener_state_object_field;
                    state = json_tokener_state_string_escape;
                    break;
                }
                if (!ADVANCE_CHAR(str, tok) || !PEEK_CHAR(c, tok))
                {
                    printbuf_memappend_fast(tok->pb, case_start,
                                            str - case_start);
                    goto out;
                }
            }
        }
        break;

        case json_tokener_state_object_field_end:
            if (c == ':')
            {
                saved_state = json_tokener_state_object_value;
                state = json_tokener_state_eatws;
            }
            else
            {
                tok->err = json_tokener_error_parse_object_key_sep;
                goto out;
            }
            break;

        case json_tokener_state_object_value:
            if (tok->depth >= tok->max_depth - 1)
            {
                tok->err = json_tokener_error_depth;
                goto out;
            }
            state = json_tokener_state_object_value_add;
            tok->depth++;
            json_tokener_reset_level(tok, tok->depth);
            goto redo_char;

        case json_tokener_state_object_value_add:
            json_object_object_add(current, obj_field_name, obj);
            free(obj_field_name);
            obj_field_name = NULL;
            saved_state = json_tokener_state_object_sep;
            state = json_tokener_state_eatws;
            goto redo_char;

        case json_tokener_state_object_sep:
            /* { */
            if (c == '}')
            {
                saved_state = json_tokener_state_finish;
                state = json_tokener_state_eatws;
            }
            else if (c == ',')
            {
                saved_state = json_tokener_state_object_field_start_after_sep;
                state = json_tokener_state_eatws;
            }
            else
            {
                tok->err = json_tokener_error_parse_object_value_sep;
                goto out;
            }
            break;
        }
        if (!ADVANCE_CHAR(str, tok))
            goto out;
    } /* while(PEEK_CHAR) */

out:
    if ((tok->flags & JSON_TOKENER_VALIDATE_UTF8) && (nBytes != 0))
    {
        tok->err = json_tokener_error_parse_utf8_string;
    }
    if (c && (state == json_tokener_state_finish) && (tok->depth == 0) &&
        (tok->flags & (JSON_TOKENER_STRICT|JSON_TOKENER_ALLOW_TRAILING_CHARS)) == JSON_TOKENER_STRICT)
    {
        /* unexpected char after JSON data */
        tok->err = json_tokener_error_parse_unexpected;
    }
    if (!c)
    {
        /* We hit an eof char (0) */
        if (state != json_tokener_state_finish && saved_state != json_tokener_state_finish)
            tok->err = json_tokener_error_parse_eof;
    }

#ifdef HAVE_USELOCALE
    uselocale(oldlocale);
    freelocale(newloc);
#elif defined(HAVE_SETLOCALE)
    setlocale(LC_NUMERIC, oldlocale);
    free(oldlocale);
#endif

    if (tok->err == json_tokener_success)
    {
        json_object *ret = json_object_get(current);
        int ii;

        /* Partially reset, so we parse additional objects on subsequent calls. */
        for (ii = tok->depth; ii >= 0; ii--)
            json_tokener_reset_level(tok, ii);
        return ret;
    }

    MC_DEBUG("json_tokener_parse_ex: error %s at offset %d\n", json_tokener_errors[tok->err],
             tok->char_offset);
    return NULL;
}

/** ZSTD_adjustCParams_internal() :
    optimize `cPar` for a given input (`srcSize` and `dictSize`).
    mostly downsizing to reduce memory consumption and initialization latency.
    Both `srcSize` and `dictSize` are optional (use 0 if unknown).
    Note : cPar is considered validated at this stage. Use ZSTD_checkCParams() to ensure that condition. */
ZSTD_compressionParameters ZSTD_adjustCParams_internal(ZSTD_compressionParameters cPar, unsigned long long srcSize, size_t dictSize)
{
    static const U64 minSrcSize = 513; /* (1<<9) + 1 */
    static const U64 maxWindowResize = 1ULL << (ZSTD_WINDOWLOG_MAX-1);
    assert(ZSTD_checkCParams(cPar)==0);

    if (dictSize && (srcSize+1<2) /* srcSize unknown */ )
        srcSize = minSrcSize;  /* presumed small when there is a dictionary */
    else
        srcSize -= 1;  /* unknown 0 => -1ULL : presumed large */

    /* resize windowLog if input is small enough, to use less memory */
    if ( (srcSize < maxWindowResize)
      && (dictSize < maxWindowResize) )  {
        U32 const tSize = (U32)(srcSize + dictSize);
        static U32 const hashSizeMin = 1 << ZSTD_HASHLOG_MIN;
        U32 const srcLog = (tSize < hashSizeMin) ? ZSTD_HASHLOG_MIN :
                            ZSTD_highbit32(tSize-1) + 1;
        if (cPar.windowLog > srcLog) cPar.windowLog = srcLog;
    }
    if (cPar.hashLog > cPar.windowLog) cPar.hashLog = cPar.windowLog;
    {   U32 const cycleLog = ZSTD_cycleLog(cPar.chainLog, cPar.strategy);
        if (cycleLog > cPar.windowLog)
            cPar.chainLog -= (cycleLog - cPar.windowLog);
    }

    if (cPar.windowLog < ZSTD_WINDOWLOG_ABSOLUTEMIN)
        cPar.windowLog = ZSTD_WINDOWLOG_ABSOLUTEMIN;  /* required for frame header */

    return cPar;
}

int wide_string_fits_in_pe(
    PE* pe,
    char* data)
{
  size_t i = 0;
  size_t space_left = available_space(pe, data);

  while (space_left >= 2)
  {
    if (data[i] == 0 && data[i + 1] == 0)
      return 1;
    space_left -= 2;
    i += 2;
  }

  return 0;
}

